def min_erasures_to_palindrome(s):
    # Check if the string is already a palindrome
    if s == s[::-1]:
        return 0

    # Try to find a character that can be removed to make the string a palindrome
    for char in set(s):
        # Calculate the number of characters to erase to make the string a palindrome
        # by removing all occurrences of the current character
        erasures = 0
        left, right = 0, len(s) - 1
        while left < right:
            if s[left] == s[right]:
                left += 1
                right -= 1
            elif s[left] == char:
                erasures += 1
                left += 1
            elif s[right] == char:
                erasures += 1
                right -= 1
            else:
                # If neither character matches, it's impossible to form a palindrome
                return -1
        return erasures

